def head(title,desc,path): return f'''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f8f9f7"><title>{escape(title)}</title><meta name="description" content="{escape(desc)}"><link rel="canonical" href="https://nodeoff.kr{path}"><meta property="og:type" content="website"><meta property="og:locale" content="ko_KR"><meta property="og:title" content="{escape(title)}"><meta property="og:description" content="{escape(desc)}"><meta property="og:url" content="https://nodeoff.kr{path}"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/style.css"></head><body>'''

def external_link(link, label=None, cls='text-link'):
 return f'<a class="{cls}" href="{escape(link["url"], quote=True)}" target="_blank" rel="noopener noreferrer">{escape(label or link["label"])} <span aria-hidden="true">↗</span><span class="sr-only"> (새 창)</span></a>'

def access_section(p):
 links=''.join(f'<li>{external_link(link)}<span class="link-state">{link["state"]}</span><span class="link-host">{urlsplit(link["url"]).netloc}</span></li>' for link in p['links'])
 return f'<section class="access-section wrap" id="access"><div><p class="eyebrow">접속 및 배포 상태</p><h2>{p["link_status"]}</h2><p class="access-note">{p["link_note"]}</p></div>'+(f'<ul class="access-links">{links}</ul>' if links else '<p class="access-empty">제품 기능과 사용 방법을 아래에 정리했습니다.</p>')+'</section>'

